services = list_services({})
summaries = for svc in services {
    res = boundary retry 2 { return search_logs({ service: svc, level: "ERROR", page: 1 }) } catch err {
        return fail("SEARCH_FAILED", svc + ": " + err.message)
    }
    items = for it in res.items { return { ts: it.ts, message: it.message } }
    return { service: svc, total_items: res.total_items, total_pages: res.total_pages, first_ts: if items != [] { return items[0].ts } else { return null }, last_ts: if items != [] { return items[list.length(items) - 1].ts } else { return null }, sample: list.slice(items, 0, 3) }
}
return summaries

p1 = search_logs({ service: "payments", level: "ERROR", page: 1 })
p2 = search_logs({ service: "payments", level: "ERROR", page: 2 })
all = p1.items + p2.items
# burst start = first timestamp where errors become dense: find largest gap between consecutive errors; burst starts after that gap
ts_list = for it in all { return time.parse(it.ts) }
pairs = fold acc = { prev: 0, max_gap: 0, burst_start: 0, first: true } for t in ts_list {
    return if acc.first { return { prev: t, max_gap: 0, burst_start: t, first: false } } else {
        gap = t - acc.prev
        return if gap > acc.max_gap { return { prev: t, max_gap: gap, burst_start: t, first: false } } else { return { prev: t, max_gap: acc.max_gap, burst_start: acc.burst_start, first: false } }
    }
}
burst_start = pairs.burst_start
deploys = get_deploys({ service: "payments" })
before = for d in deploys {
    skip if time.parse(d.deployed_at) > burst_start
    return { sha: d.sha, at: time.parse(d.deployed_at) }
}
sorted_d = list.sort_by(before, "at", "desc")
chosen = sorted_d[0]
owner = get_service_owners({ service: "payments" })
result = submit_result({ answer: { service: "payments", deploy_sha: chosen.sha, owner_email: owner.owner_email } })
return { burst_start: time.format(burst_start), deploy_sha: chosen.sha, deployed_at: time.format(chosen.at), owner_email: owner.owner_email, submitted: result.recorded }

